103	The whole manifest is rejected unless every record can be registered or
104	confirmed as a duplicate: a batch id already stored or seen earlier in the
105	manifest must match product, quantity and unit exactly, or none of the new
106	batches are saved and the error names the 1-based record position, the batch
107	id and the mismatching field(s). On success stdout contains one JSON object
108	whose results array keeps manifest order, each entry carrying the normalized
109	four fields plus status "created" or "duplicate"; new batches are appended
110	in first-occurrence order and an all-duplicate manifest leaves the registry
111	file byte-for-byte untouched.
112	
113	Batch, product and unit values have leading and trailing whitespace removed
114	and must be non-empty afterwards; interior characters and casing are kept
115	("B1" and "b1" are different batches). One invocation registers one batch.
116	
117	Batch, product and unit must be valid UTF-8 text in every source: command
118	line flags, import manifest records and stored registry records. A value
119	containing malformed UTF-8 bytes (or a JSON string holding a lone surrogate
120	escape such as "\ud800") is rejected and never replaced with the U+FFFD
121	replacement character, so distinct inputs cannot collapse onto one batch
122	id; the error names the parameter, or the manifest/registry file with the
123	1-based record position and field (plus the batch id only when it is itself
124	valid and unambiguous). The same rule applies to field NAMES in the JSON
125	files: a name with malformed bytes or a lone surrogate escape rejects the
126	whole operation with an invalid-field-name error naming the file (plus the
127	1-based record position, and the batch id when unambiguous, for record
128	level problems) — it is never reported as an unknown field under the
129	substituted text. A genuinely entered U+FFFD character is ordinary
130	text, non-ASCII ids (Chinese text, emoji, ...) are welcome, and a JSON
131	escape means the same text as the character written directly.
132	
133	On success stdout contains a single JSON object, e.g.
134	  {"batch":"B-001","product":"P-7","quantity":120,"unit":"kg","status":"created"}
135	status is "created" for a new record and "duplicate" when the same batch was
136	already registered with the identical product, quantity and unit; a duplicate
137	does not rewrite the file and is safe to retry. Registering an existing batch
138	with any different field is rejected; the error names the batch and the
139	mismatching field(s) and no record is changed.
140	
141	registry file format (UTF-8 JSON, human-inspectable):
142	  {
143	    "version": 1,
144	    "batches": [
145	      {"batch": "B-001", "product": "P-7", "quantity": 120, "unit": "kg"}
146	    ]
147	  }
148	A missing file is created on first registration. The registry path may be a
149	symbolic link to an existing registry file: new batches are saved into the
150	linked file (a relative link target is resolved against the link's own
151	directory), the link itself is left untouched and the target keeps its
152	permissions. A link whose target does not exist, or a loop of links, is
153	rejected — the target is never created and the link is never replaced. An
154	existing file that is empty, cannot be read in this format, or contains
155	several records with the same batch number is rejected outright and never
156	overwritten. "This format"
157	is strict: the root object must carry exactly version (the integer 1) and
158	batches (an array, empty allowed), each record exactly the four lowercase
159	fields batch, product, quantity and unit; missing, null, mistyped, unknown
160	or case-variant fields (Version, Batch, ...) are rejected, and so is any
161	field appearing twice in one object — even with identical values, even when
162	one spelling hides behind a JSON escape. The error names the file, the
163	field and the reason, plus the 1-based record position (and the batch id
164	when it is unambiguous) for record-level problems. Failures print
165	the reason to stderr and exit non-zero without touching the registry.
166	`
167	}
168	
169	func runBatchRegister(args []string, stdout io.Writer) error {
170		fs := flag.NewFlagSet("batch-register", flag.ContinueOnError)
171		fs.SetOutput(io.Discard)
172		registryPath := fs.String("registry", "", "registry `file` to read and write")
173		batchRaw := fs.String("batch", "", "batch number (unique within the registry)")
174		productRaw := fs.String("product", "", "product number")
175		quantityRaw := fs.String("quantity", "", "positive decimal integer quantity")
176		unitRaw := fs.String("unit", "", "measurement unit")
177		if err := fs.Parse(args); err != nil {
178			if errors.Is(err, flag.ErrHelp) {
179				fmt.Fprint(stdout, rootUsage())
180				return nil
181			}
182			return &usageError{msg: "batch-register: " + err.Error(), usage: batchRegisterUsage}
183		}
184		if fs.NArg() != 0 {
185			return &usageError{
186				msg:   fmt.Sprintf("batch-register: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
187				usage: batchRegisterUsage,
188			}
189		}
190	
191		// Missing or malformed input must never create or modify the registry
192		// file, so required flags are checked before reading or writing anything.
193		required := []struct {
194			name  string
195			value string
196		}{
197			{"--registry", *registryPath},
198			{"--batch", *batchRaw},
199			{"--product", *productRaw},
200			{"--quantity", *quantityRaw},
201			{"--unit", *unitRaw},
202		}
203		var missing []string
204		for _, f := range required {
205			if f.value == "" {
206				missing = append(missing, f.name)
207			}
208		}
209		if len(missing) > 0 {
210			return &usageError{
211				msg:   "batch-register: missing required flag(s): " + strings.Join(missing, ", "),
212				usage: batchRegisterUsage,
213			}
214		}
215	
216		batch, err := batchreg.NormalizeField(*batchRaw)
217		if err != nil {
218			return &usageError{msg: "batch-register: invalid --batch: " + err.Error(), usage: batchRegisterUsage}
219		}
220		product, err := batchreg.NormalizeField(*productRaw)
221		if err != nil {
222			return &usageError{msg: "batch-register: invalid --product: " + err.Error(), usage: batchRegisterUsage}
223		}
224		unit, err := batchreg.NormalizeField(*unitRaw)
225		if err != nil {
226			return &usageError{msg: "batch-register: invalid --unit: " + err.Error(), usage: batchRegisterUsage}
227		}
228		quantity, err := batchreg.ParseQuantity(*quantityRaw)
229		if err != nil {
230			return &usageError{msg: "batch-register: invalid --quantity: " + err.Error(), usage: batchRegisterUsage}
231		}
232	
233		reg, existed, err := batchreg.Load(*registryPath)
234		if err != nil {
235			return err
236		}
237		outcome, err := batchreg.Register(reg, batchreg.Input{
238			Batch: batch, Product: product, Quantity: quantity, Unit: unit,
239		})
240		if err != nil {
241			return err
242		}
243		if outcome.Created {
244			if err := batchreg.Save(*registryPath, reg); err != nil {
245				if !existed {
246					// Nothing was registered before; drop any partial new file.
247					removePartialNewRegistry(*registryPath)
248				}
249				return err
250			}
251		}
252	
253		status := "duplicate"
254		if outcome.Created {
255			status = "created"
256		}
257		result := struct {
258			Batch    string `json:"batch"`
259			Product  string `json:"product"`
260			Quantity int64  `json:"quantity"`
261			Unit     string `json:"unit"`
262			Status   string `json:"status"`
263		}{
264			Batch:    outcome.Batch.Batch,
265			Product:  outcome.Batch.Product,
266			Quantity: outcome.Batch.Quantity,
267			Unit:     outcome.Batch.Unit,
268			Status:   status,
269		}
270		payload, err := json.Marshal(result)
271		if err != nil {
272			return err
273		}
274		_, err = fmt.Fprintln(stdout, string(payload))
275		return err
276	}
277	
278	func runBatchImport(args []string, stdout io.Writer) error {
279		fs := flag.NewFlagSet("batch-import", flag.ContinueOnError)
280		fs.SetOutput(io.Discard)
281		registryPath := fs.String("registry", "", "registry `file` to read and write")
282		inputPath := fs.String("input", "", "read-only JSON manifest `file` to import")
283		if err := fs.Parse(args); err != nil {
284			if errors.Is(err, flag.ErrHelp) {
285				fmt.Fprint(stdout, rootUsage())
286				return nil
287			}
288			return &usageError{msg: "batch-import: " + err.Error(), usage: batchImportUsage}
289		}
290		if fs.NArg() != 0 {
291			return &usageError{
292				msg:   fmt.Sprintf("batch-import: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
293				usage: batchImportUsage,
294			}
295		}
296		if *registryPath == "" || *inputPath == "" {
297			var missing []string
298			if *registryPath == "" {
299				missing = append(missing, "--registry")
300			}
301			if *inputPath == "" {
302				missing = append(missing, "--input")
303			}
304			return &usageError{
305				msg:   "batch-import: missing required flag(s): " + strings.Join(missing, ", "),
306				usage: batchImportUsage,
307			}
308		}
309	
310		// The manifest is read-only and is parsed (and fully validated) before
311		// the registry is loaded or written, so bad input cannot touch it.
312		data, err := os.ReadFile(*inputPath)
313		if err != nil {
314			return fmt.Errorf("batch-import: cannot read input file %q: %w", *inputPath, err)
315		}
316		inputs, err := batchreg.ParseManifest(data)
317		if err != nil {
318			return fmt.Errorf("batch-import: invalid input file %q: %w", *inputPath, err)
319		}
320	
321		reg, existed, err := batchreg.Load(*registryPath)
322		if err != nil {
323			return fmt.Errorf("batch-import: %w", err)
324		}
325		outcomes, err := batchreg.Import(reg, inputs)
326		if err != nil {
327			return fmt.Errorf("batch-import: %w", err)
328		}
329	
330		type importResultJSON struct {
331			Batch    string `json:"batch"`
332			Product  string `json:"product"`
333			Quantity int64  `json:"quantity"`
334			Unit     string `json:"unit"`
335			Status   string `json:"status"`
336		}
337		results := make([]importResultJSON, len(outcomes))
338		anyCreated := false
339		for i, o := range outcomes {
340			status := "duplicate"
341			if o.Created {
342				status = "created"
343				anyCreated = true
344			}
345			results[i] = importResultJSON{
346				Batch:    o.Batch.Batch,
347				Product:  o.Batch.Product,
348				Quantity: o.Batch.Quantity,
349				Unit:     o.Batch.Unit,
350				Status:   status,
351			}
352		}
353	
354		// An all-duplicate manifest must leave bytes and mtime untouched, so the
355		// registry is written only when at least one record was newly created.
356		if anyCreated {
357			if err := batchreg.Save(*registryPath, reg); err != nil {
358				if !existed {
359					// The registry never existed before this import; drop any
360					// partial new file so a failed save leaves nothing behind.
361					removePartialNewRegistry(*registryPath)
362				}
363				return fmt.Errorf("batch-import: %w", err)
364			}
365		}
366	
367		payload, err := json.Marshal(struct {
368			Results []importResultJSON `json:"results"`
369		}{Results: results})
370		if err != nil {
371			return fmt.Errorf("batch-import: %w", err)
372		}
373		_, err = fmt.Fprintln(stdout, string(payload))
374		if err != nil {
375			return fmt.Errorf("batch-import: %w", err)
376		}
377		return nil
378	}
379	
380	// removePartialNewRegistry drops a partially written new registry file after
381	// a failed first save. A symbolic link is never removed: the link is the
382	// user's pointer to the real registry file, not a partial creation of this
383	// run.
384	func removePartialNewRegistry(path string) {
385		info, err := os.Lstat(path)
386		if err != nil || info.Mode()&os.ModeSymlink != 0 {
387			return
388		}
389		os.Remove(path)
390	}
391	
392	func runDemo() {
393		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
394			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
395		if err := govflow.Vote(&proposal, 700, true); err != nil {
396			fmt.Println("vote refused:", err)
397		}
398		if err := govflow.Vote(&proposal, 200, false); err != nil {
399			fmt.Println("vote refused:", err)
400		}
401		next := govflow.Tally(&proposal)
402		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
403		proposal.State = next
404		proposal.TimelockEnd = 400
405		fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
406	}
