		{Batch: "B2", Product: "P-8", Quantity: 1, Unit: "box"}, // created
		{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}, // duplicate of record 1
		{Batch: "B0", Product: "P-0", Quantity: 5, Unit: "box"}, // duplicate of the stored record
