1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"flag"
8		"fmt"
9		"io"
10		"os"
11		"os/exec"
12		"path/filepath"
13		"strconv"
14		"strings"
15		"testing"
16		"time"
17	
18		"github.com/gzhysuiioo/govflow-proposals/govflow/batchreg"
19	)
20	
21	// End-to-end regression for batch-import's all-records-or-none promise at the
22	// point where it is most easily broken: a SAVE failure. The manifest used here
23	// is legal under every field rule and conflicts with nothing — some records
24	// confirm batches already registered (one of them padded with whitespace), one
25	// record repeats a batch introduced earlier in the same manifest, and several
26	// batches are new — so a failure can only originate from the save itself,
27	// never from invalid input or a batch conflict.
28	//
29	// Two real save failures are injected deterministically through batchreg's
30	// step hooks (no disk exhaustion, no filesystem fault, no special account):
31	//
32	//   - the new content write stops while the new table is incomplete;
33	//   - the new table is fully prepared in the temporary file but replacing the
34	//     registry file is refused.
35	//
36	// Each is run against an existing registry and against a path where no
37	// registry exists yet. Whatever step fails, batch-import must report failure
38	// to its caller: non-zero exit code, stderr naming the target registry path
39	// and the concrete save reason, empty stdout, the existing registry kept
40	// byte-for-byte and timestamp-for-timestamp (or the missing target still
41	// absent), no partial table and no leftover temporary file, and the
42	// read-only manifest exactly as submitted. Success controls with the very
43	// same manifest prove the manifest imports normally and that the JSON results
44	// match what the registry finally holds, record by record and field by field.
45	//
46	// The failure scenarios run in a real child process — the test binary
47	// re-invoked with -wrap.batch-import — so the assertions cover the actual
48	// process contract (exit code, stdout, stderr) rather than an in-process
49	// error return, while staying fully offline: the child is this same binary.
50	
51	var wrapBatchImport = flag.Bool("wrap.batch-import", false, "internal: run one batch-import invocation and exit")
