72	// runWrappedBatchImport performs exactly one batch-import against the files
73	// named in WRAP_REGISTRY/WRAP_INPUT, optionally failing one save step as
74	// selected by WRAP_FAULT. Exit codes mimic the real command: 1 for a reported
75	// batch-import failure (message written to stderr like main does), 3 for a
76	// harness problem inside the child, 0 for success.
77	func runWrappedBatchImport() int {
78		registry := os.Getenv("WRAP_REGISTRY")
79		input := os.Getenv("WRAP_INPUT")
80		reason := os.Getenv("WRAP_REASON")
81		harnessFail := func(format string, args ...any) int {
82			fmt.Fprintf(os.Stderr, "wrap harness: "+format+"\n", args...)
83			return 3
84		}
85		// harnessExit reports a broken test harness from inside an injected hook,
86		// whose signature allows only an error; the parent treats code 3 as a
87		// harness failure rather than a command failure.
88		harnessExit := func(format string, args ...any) error {
89			fmt.Fprintf(os.Stderr, "wrap harness: "+format+"\n", args...)
90			os.Exit(3)
91			return nil
92		}
93		switch saveFault(os.Getenv("WRAP_FAULT")) {
94		case faultWrite:
95			// Part of the new content genuinely reaches the temporary file, then
96			// the write stops with the new table incomplete.
97			batchreg.WriteTempContent = func(f *os.File, data []byte) (int, error) {
98				half := len(data) / 2
99				if _, err := f.Write(data[:half]); err != nil {
100					fmt.Fprintf(os.Stderr, "wrap harness: setup write failed: %v\n", err)
101					os.Exit(3)
102				}
103				return half, errors.New(reason)
104			}
105		case faultRename:
106			// The complete new table must be ready before the replacement is
107			// refused; markers are checked on the prepared temporary file.
108			markers := strings.Split(os.Getenv("WRAP_MARKERS"), ",")
109			batchreg.RenameTempFile = func(oldpath, newpath string) error {
110				if newpath != registry {
111					return harnessExit("rename must target %q, got %q", registry, newpath)
112				}
113				prepared, err := os.ReadFile(oldpath)
114				if err != nil {
115					return harnessExit("prepared temporary file is unreadable: %v", err)
116				}
117				for _, marker := range markers {
118					if !bytes.Contains(prepared, []byte(marker)) {
119						return harnessExit("prepared content is missing %q: %s", marker, prepared)
120					}
121				}
122				return errors.New(reason)
123			}
124		case faultNone:
125		default:
126			return harnessFail("unknown fault %q", os.Getenv("WRAP_FAULT"))
127		}
128		if err := runBatchImport([]string{"--registry", registry, "--input", input}, os.Stdout); err != nil {
129			fmt.Fprintln(os.Stderr, "govflow:", err)
130			return 1
131		}
132		return 0
133	}
