228	// writeManifest serializes the shared rows as one JSON array file.
229	func writeManifest(t *testing.T, path string, rows []manifestRow) []byte {
230		t.Helper()
231		var buf bytes.Buffer
232		buf.WriteByte('[')
233		for i, r := range rows {
234			if i > 0 {
235				buf.WriteByte(',')
236			}
237			data, err := json.Marshal(r)
238			if err != nil {
239				t.Fatal(err)
240			}
241			buf.Write(data)
242		}
243		buf.WriteByte(']')
244		if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
245			t.Fatal(err)
246		}
247		return buf.Bytes()
248	}
