250	// runImportChild re-executes the test binary in wrapped one-command mode with
251	// the chosen fault and returns the child's exit code plus captured output.
252	// existingRegistry says whether the target file pre-exists, which decides
253	// which batch ids the fully prepared new table must contain.
254	func runImportChild(t *testing.T, registry, manifest string, fault saveFault, reason string, existingRegistry bool) (code int, stdout, stderr []byte) {
255		t.Helper()
256		exe, err := os.Executable()
257		if err != nil {
258			t.Fatal(err)
259		}
260		// Every manifest batch must be present in the prepared temporary file
261		// before the replacement is refused; B-OLD-3 additionally appears only
262		// when it was already stored.
263		markers := []string{
264			"B-OLD-1", "B-OLD-2", "B-NEW-1", "B-NEW-2", "B-NEW-3", "苹果", "新产品😀",
265		}
266		if existingRegistry {
267			markers = append(markers, "B-OLD-3")
268		}
269		cmd := exec.Command(exe, "-wrap.batch-import")
270		cmd.Env = append(os.Environ(),
271			"WRAP_REGISTRY="+registry,
272			"WRAP_INPUT="+manifest,
273			"WRAP_FAULT="+string(fault),
274			"WRAP_REASON="+reason,
275			"WRAP_MARKERS="+strings.Join(markers, ","),
276		)
277		var outBuf, errBuf bytes.Buffer
278		cmd.Stdout = &outBuf
279		cmd.Stderr = &errBuf
280		runErr := cmd.Run()
281		stdout = outBuf.Bytes()
282		stderr = errBuf.Bytes()
283		if runErr == nil {
284			return 0, stdout, stderr
285		}
286		var exitErr *exec.ExitError
287		if errors.As(runErr, &exitErr) {
288			return exitErr.ExitCode(), stdout, stderr
289		}
290		t.Fatalf("child process did not start: %v", runErr)
291		return 0, nil, nil
292	}
