294	// assertNoSaveLeftovers walks dir and fails if a save temporary file
295	// (".govflow-registry-*") or any file other than allowed survived.
296	func assertNoSaveLeftovers(t *testing.T, dir string, allowed ...string) {
297		t.Helper()
298		keep := map[string]bool{}
299		for _, name := range allowed {
300			keep[name] = true
301		}
302		err := filepath.WalkDir(dir, func(path string, d os.DirEntry, err error) error {
303			if err != nil || d.IsDir() {
304				return nil
305			}
306			if strings.HasPrefix(d.Name(), ".govflow-registry-") {
307				t.Errorf("failed import left a temporary registry file behind: %s", path)
308			}
309			if !keep[d.Name()] {
310				t.Errorf("failed import left an unexpected file behind: %s", path)
311			}
312			return nil
313		})
314		if err != nil {
315			t.Fatal(err)
316		}
317	}
