319	// TestBatchImportCLISaveFailuresAreAllOrNothing runs both injected save
320	// failures against both target states. The manifest is the shared legal one;
321	// the failure must be reported as a save failure and leave the world exactly
322	// as it was before the command.
323	func TestBatchImportCLISaveFailuresAreAllOrNothing(t *testing.T) {
324		causes := map[saveFault]string{
325			faultWrite:  "injected save failure: new registry content not fully written",
326			faultRename: "injected save failure: complete new registry cannot replace the target",
327		}
328		for _, fault := range []saveFault{faultWrite, faultRename} {
329			for _, target := range []string{"existing registry", "missing registry"} {
330				name := string(fault) + "/" + strings.ReplaceAll(target, " ", "_")
331				t.Run(name, func(t *testing.T) {
332					dir := t.TempDir()
333					registry := filepath.Join(dir, "reg.json")
334					manifest := filepath.Join(dir, "arrivals.json")
335					existing := target == "existing registry"
336					var originalBytes []byte
337					if existing {
338						writeFile(t, registry, importFailureRegistryJSON)
339						if err := os.Chtimes(registry, importFailurePinnedModTime, importFailurePinnedModTime); err != nil {
340							t.Fatal(err)
341						}
342						originalBytes = readFileSnapshot(t, registry)
343					}
344					manifestBytes := writeManifest(t, manifest, importFailureManifestRows)
345	
346					code, stdout, stderr := runImportChild(t, registry, manifest, fault, causes[fault], existing)
347	
348					// The caller must observe a command failure, not a success.
349					if code != 1 {
350						t.Fatalf("exit code = %d, want 1; stderr:\n%s", code, stderr)
351					}
352					if len(bytes.TrimSpace(stdout)) != 0 {
353						t.Fatalf("stdout must stay empty on save failure, got %q", stdout)
354					}
355					msg := string(stderr)
356					// stderr must identify the command, the target registry path
357					// and the concrete save reason.
358					for _, want := range []string{
359						"govflow: batch-import:",
360						"cannot save registry",
361						registry,
362						causes[fault],
363					} {
364						if !strings.Contains(msg, want) {
365							t.Fatalf("stderr must contain %q:\n%s", want, msg)
366						}
367					}
368					// The manifest is legal and conflict-free (proven by the
369					// success controls below); the failure wording must never
370					// masquerade as invalid input or a batch conflict.
371					for _, mustNot := range []string{"invalid input", "conflicts with"} {
372						if strings.Contains(msg, mustNot) {
373							t.Fatalf("a save failure must not be reported as %q:\n%s", mustNot, msg)
374						}
375					}
376	
377					if existing {
378						// The existing registry survives with exact bytes and
379						// modification time and still loads with its original
380						// records, fields and order.
381						info, err := os.Stat(registry)
382						if err != nil {
383							t.Fatalf("the original registry must still exist: %v", err)
384						}
385						if !info.ModTime().Equal(importFailurePinnedModTime) {
386							t.Fatalf("failed import changed the registry mtime: got %v, want %v",
387								info.ModTime(), importFailurePinnedModTime)
388						}
389						after := readFileSnapshot(t, registry)
390						if !bytes.Equal(after, originalBytes) {
391							t.Fatalf("failed import changed the registry bytes:\nbefore: %s\nafter:  %s", originalBytes, after)
392						}
393						if bytes.Contains(after, []byte("B-NEW-")) {
394							t.Fatalf("part of the manifest landed in the registry: %s", after)
395						}
396						stored := readStoredBatches(t, registry)
397						wantStored := []registerResult{
398							{Batch: "B-OLD-1", Product: "P-1", Quantity: 7, Unit: "kg"},
399							{Batch: "B-OLD-2", Product: "苹果", Quantity: 80, Unit: "箱"},
400							{Batch: "B-OLD-3", Product: "P-3", Quantity: 9223372036854775807, Unit: "m"},
401						}
402						if len(stored) != len(wantStored) {
403							t.Fatalf("registry must keep exactly its original batches, got %+v", stored)
404						}
405						for i, want := range wantStored {
406							got := stored[i]
407							got.Status = ""
408							if got != want {
409								t.Fatalf("original record %d = %+v, want %+v", i+1, got, want)
410							}
411						}
412					} else {
413						// With no prior registry there must still be no file: not
414						// an empty registry, not the first few manifest rows.
415						if _, err := os.Stat(registry); !os.IsNotExist(err) {
416							t.Fatalf("failed import must not create the registry, stat err=%v", err)
417						}
418					}
419					assertNoSaveLeftovers(t, dir, filepath.Base(manifest), filepath.Base(registry))
420					assertFileUnchanged(t, manifest, manifestBytes)
421				})
422			}
423		}
424	}
