532		if err := os.Chtimes(registry, importFailurePinnedModTime, importFailurePinnedModTime); err != nil {
533			t.Fatal(err)
534		}
535		manifestBytes := writeManifest(t, manifest, importFailureManifestRows)
536	
537		var stdout bytes.Buffer
538		if err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout); err != nil {
539			t.Fatalf("the legal manifest must import when the save does not fail: %v", err)
540		}
541	
542		// A real save must have happened (new batches exist), observable as a new
543		// mtime rather than the pinned one.
