564	func TestBatchImportCLISaveSuccessWithMissingRegistry(t *testing.T) {
565		dir := t.TempDir()
566		registry := filepath.Join(dir, "reg.json")
567		manifest := filepath.Join(dir, "arrivals.json")
568		manifestBytes := writeManifest(t, manifest, importFailureManifestRows)
569	
570		var stdout bytes.Buffer
571		if err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout); err != nil {
572			t.Fatalf("the legal manifest must import and create the registry: %v", err)
573		}
574	
575		assertImportResults(t, stdout.Bytes(), manifestResultsWhenMissing)
576		stored := readStoredBatches(t, registry)
577		assertStoredBatches(t, registry, storedBatchesWhenMissing)
578		assertResultsMatchRegistry(t, manifestResultsWhenMissing, stored)
579		assertFileUnchanged(t, manifest, manifestBytes)
580		assertNoSaveLeftovers(t, dir, filepath.Base(manifest), filepath.Base(registry))
581	}
582	
583	// The save-failure path must surface the quoted target path verbatim; this
584	// guards the wording the failure scenarios assert on, in a direct check that
585	// reads naturally when it breaks.
586	func TestBatchImportCLISaveFailureWordingNamesPath(t *testing.T) {
587		dir := t.TempDir()
588		registry := filepath.Join(dir, "reg.json")
589		manifest := filepath.Join(dir, "arrivals.json")
590		writeFile(t, registry, importFailureRegistryJSON)
591		writeManifest(t, manifest, importFailureManifestRows)
592	
593		code, stdout, stderr := runImportChild(t, registry, manifest, faultRename, "injected replacement refusal", true)
594		if code != 1 {
595			t.Fatalf("exit code = %d, want 1; stderr:\n%s", code, stderr)
596		}
597		if len(stdout) != 0 {
598			t.Fatalf("stdout must be empty, got %q", stdout)
599		}
600		want := "cannot save registry " + strconv.Quote(registry) + ": injected replacement refusal"
601		if !strings.Contains(string(stderr), want) {
602			t.Fatalf("stderr must contain %q:\n%s", want, stderr)
603		}
604	}
