836	// readStoredBatches decodes the registry file into its records, in file order.
837	func readStoredBatches(t *testing.T, path string) []registerResult {
838		t.Helper()
839		data, err := os.ReadFile(path)
840		if err != nil {
841			t.Fatal(err)
842		}
843		var stored struct {
844			Version int              `json:"version"`
845			Batches []registerResult `json:"batches"`
846		}
847		if err := json.Unmarshal(data, &stored); err != nil {
848			t.Fatalf("registry file does not decode: %v (%s)", err, data)
849		}
850		if stored.Version != 1 {
851			t.Fatalf("registry version = %d, want 1", stored.Version)
852		}
853		return stored.Batches
854	}
