856	// pinRegistry reads the registry and pins a distinctive past mtime so any
857	// rewrite — even one reproducing identical bytes — is observable.
858	func pinRegistry(t *testing.T, path string) (content []byte, pinned time.Time) {
859		t.Helper()
860		pinned = time.Date(2004, time.May, 6, 7, 8, 9, 0, time.UTC)
861		if err := os.Chtimes(path, pinned, pinned); err != nil {
862			t.Fatal(err)
863		}
864		content, err := os.ReadFile(path)
865		if err != nil {
866			t.Fatal(err)
867		}
868		return content, pinned
869	}
