871	// assertRegistryUntouched fails if the file's bytes or mtime differ from the
872	// pinned snapshot.
873	func assertRegistryUntouched(t *testing.T, path string, content []byte, pinned time.Time) {
874		t.Helper()
875		after, err := os.ReadFile(path)
876		if err != nil {
877			t.Fatal(err)
878		}
