1003				msg := err.Error()
1004				if !strings.Contains(msg, strconv.Quote("B-001")) {
1005					t.Fatalf("error must name the batch: %v", msg)
1006				}
1007				for _, field := range tc.fields {
1008					if !strings.Contains(msg, field) {
1009						t.Fatalf("error must report differing field %q: %v", field, msg)
1010					}
1011				}
1012				assertRegistryUntouched(t, registry, content, pinned)
1013	
1014				batches := readStoredBatches(t, registry)
1015				if len(batches) != 2 || batches[1].Product != "P-7" ||
1016					batches[1].Quantity != 120 || batches[1].Unit != "kg" {
1017					t.Fatalf("the conflict must not overwrite the stored record: %v", batches)
1018				}
1019			})
1020		}
1021	}
1022	
1023	// Batch ids compare byte for byte: "b-001" is a different id from "B-001" and
1024	// registers as its own record, after which it confirms duplicates of its own.
1025	func TestBatchRegisterCLIBatchIDCaseSensitive(t *testing.T) {
1026		dir := t.TempDir()
1027		registry := filepath.Join(dir, "reg.json")
1028	
1029		if _, err := registerCLI(t, registry, "B-001", "P-7", "120", "kg"); err != nil {
1030			t.Fatal(err)
1031		}
1032		stdout, err := registerCLI(t, registry, "b-001", "P-7", "120", "kg")
1033		if err != nil {
1034			t.Fatalf("a case-distinct batch id must register: %v", err)
1035		}
1036		if res := decodeRegisterResult(t, stdout); res.Status != "created" || res.Batch != "b-001" {
1037			t.Fatalf("got %+v, want created b-001", res)
1038		}
1039	
1040		batches := readStoredBatches(t, registry)
1041		if len(batches) != 2 || batches[0].Batch != "B-001" || batches[1].Batch != "b-001" {
1042			t.Fatalf("want B-001 and b-001 as separate records in order, got %v", batches)
1043		}
1044	
1045		stdout, err = registerCLI(t, registry, "b-001", "P-7", "120", "kg")
1046		if err != nil {
1047			t.Fatal(err)
1048		}
1049		if res := decodeRegisterResult(t, stdout); res.Status != "duplicate" {
1050			t.Fatalf("got %+v, want duplicate", res)
1051		}
1052		if batches := readStoredBatches(t, registry); len(batches) != 2 {
1053			t.Fatalf("duplicate confirmation added a record: %v", batches)
1054		}
1055	}
1056	
1057	// Quantities compare as integers right up to the int64 ceiling: MaxQuantity
1058	// registers and confirms as a duplicate, one less conflicts on quantity, and
1059	// anything above the ceiling is rejected as an illegal --quantity value —
1060	// never a created or duplicate result.
1061	func TestBatchRegisterCLIQuantityBoundaries(t *testing.T) {
1062		dir := t.TempDir()
1063		registry := filepath.Join(dir, "reg.json")
1064		const max = "9223372036854775807"
1065	
1066		stdout, err := registerCLI(t, registry, "B-MAX", "P-7", max, "kg")
1067		if err != nil {
