1069		}
1070		if res := decodeRegisterResult(t, stdout); res.Status != "created" || res.Quantity != 9223372036854775807 {
1071			t.Fatalf("got %+v, want created with quantity 9223372036854775807", res)
1072		}
1073	
1074		stdout, err = registerCLI(t, registry, "B-MAX", "P-7", max, "kg")
1075		if err != nil {
1076			t.Fatalf("the maximum quantity must confirm as duplicate: %v", err)
1077		}
1078		if res := decodeRegisterResult(t, stdout); res.Status != "duplicate" || res.Quantity != 9223372036854775807 {
1079			t.Fatalf("got %+v, want duplicate with quantity 9223372036854775807", res)
1080		}
1081	
1082		content, pinned := pinRegistry(t, registry)
1083	
1084		stdout, err = registerCLI(t, registry, "B-MAX", "P-7", "9223372036854775806", "kg")
1085		if err == nil {
1086			t.Fatal("one less than the stored quantity must conflict, not confirm")
1087		}
1088		if stdout != "" {
1089			t.Fatalf("stdout must stay empty on conflict, got %q", stdout)
1090		}
1091		if msg := err.Error(); !strings.Contains(msg, strconv.Quote("B-MAX")) || !strings.Contains(msg, "quantity") {
1092			t.Fatalf("error must name the batch and the quantity field: %v", msg)
1093		}
1094		assertRegistryUntouched(t, registry, content, pinned)
1095	
1096		stdout, err = registerCLI(t, registry, "B-OVER", "P-7", "9223372036854775808", "kg")
1097		if err == nil {
1098			t.Fatal("a quantity above the maximum must be rejected")
1099		}
1100		if stdout != "" {
1101			t.Fatalf("stdout must stay empty on invalid input, got %q", stdout)
1102		}
1103		if msg := err.Error(); !strings.Contains(msg, "--quantity") || !strings.Contains(msg, max) {
1104			t.Fatalf("error must reject --quantity against the maximum %s: %v", max, msg)
1105		}
1106		assertRegistryUntouched(t, registry, content, pinned)
1107	
1108		if batches := readStoredBatches(t, registry); len(batches) != 1 || batches[0].Quantity != 9223372036854775807 {
1109			t.Fatalf("failures must not add or alter records: %v", batches)
